export PATH="$HOME/.local/bin:$PATH" && uv run python3 -c "
import pandas as pd
import numpy as np
train = pd.read_csv('train.csv')
y = train['target'].values
X = train.drop('target', axis=1).values

# Check ALL pairwise products
print('Checking all pairwise product correlations...')
best = []
for i in range(50):
    for j in range(i+1, 50):
        c = np.corrcoef(X[:,i]*X[:,j], y)[0,1]
        if abs(c) > 0.01:
            best.append((abs(c), i, j, c))

best.sort(reverse=True)
for ac, i, j, c in best[:20]:
    print(f'x{i+1:02d}*x{j+1:02d}: {c:.4f}')

# Also check triple products of the best pairs
if best:
    print()
    print('Checking triple products...')
    top_feats = set()
    for _, i, j, _ in best[:10]:
        top_feats.add(i)
        top_feats.add(j)
    top_feats = list(top_feats)
    for i in top_feats[:10]:
        for j in top_feats[:10]:
            for k in top_feats[:10]:
                if i < j < k:
                    c = np.corrcoef(X[:,i]*X[:,j]*X[:,k], y)[0,1]
                    if abs(c) > 0.02:
                        print(f'x{i+1:02d}*x{j+1:02d}*x{k+1:02d}: {c:.4f}')
" 2>&1

